-- Generated from js/engine.js v2 and experimental SQL. Review and validate before applying.
create table side_lite_private.side_marketing_factors(amount integer primary key, factor double precision not null);
alter table side_lite_private.side_marketing_factors enable row level security;
revoke all on side_lite_private.side_marketing_factors from public, anon, authenticated, service_role;
grant select on side_lite_private.side_marketing_factors to side_lite_closer;
grant select on public.lite_events to side_lite_closer;

create or replace function side_lite_private.side_engine_v2(p_cash bigint, p_stock jsonb, p_decision jsonb,
  p_costs jsonb, p_event jsonb, p_seed text, p_company text)
returns jsonb language plpgsql set search_path = '' as $$
declare
  h bigint := 2166136261; key text := p_seed || ':' || p_company; i integer;
  v double precision; quality text; quantity bigint; price bigint; marketing bigint;
  unit_cost bigint; purchase bigint; demand bigint; sold bigint; available bigint := 0;
  left_to_sell bigint; consumed bigint; cost_of_sales bigint := 0; revenue bigint; cash_end bigint;
  stock jsonb := coalesce(p_stock,'[]'::jsonb); remaining_stock jsonb := '[]'::jsonb; batch jsonb;
  quality_factor double precision; demand_factor double precision; purchase_factor double precision; p_marketing_factor double precision;
begin
  if p_seed is null or p_company is null then raise exception 'missing seed'; end if;
  if p_decision is null then
    return jsonb_build_object('cashStart',p_cash,'cashEnd',p_cash,'purchase',0,'marketing',0,
      'revenue',0,'costOfSales',0,'profit',0,'sold',0,'demand',0,'inventory',stock,'event',p_event,'ruleVersion',2);
  end if;
  for i in 1..length(key) loop
    h := ((h # ascii(substr(key,i,1))::bigint) * 16777619) % 4294967296;
  end loop;
  v := 0.95::float8 + (h % 101)::float8 / 1000::float8;
  quality := p_decision->>'quality'; quantity := (p_decision->>'quantity')::bigint;
  price := (p_decision->>'price')::bigint; marketing := (p_decision->>'marketingAmount')::bigint;
  quality_factor := case quality when 'basic' then 0.85::float8 when 'standard' then 1::float8 when 'premium' then 1.18::float8 else null end;
  if quality_factor is null or quantity < 0 or price < 1 or marketing < 0 or (marketing > 0 and marketing < 200) or marketing > 10000 then raise exception 'invalid decision'; end if;
  select factor into strict p_marketing_factor from side_lite_private.side_marketing_factors where amount=marketing;
  demand_factor := coalesce((p_event->>'demand')::float8,1::float8);
  purchase_factor := coalesce((p_event->>'purchase')::float8,1::float8);
  unit_cost := floor((p_costs->>quality)::float8 * purchase_factor + 0.5)::bigint;
  purchase := quantity * unit_cost;
  if p_cash < purchase + marketing then raise exception 'insufficient cash'; end if;
  if quantity > 0 then stock := stock || jsonb_build_array(jsonb_build_object('quantity',quantity,'unitCost',unit_cost)); end if;
  demand := floor(300::float8 * greatest(0.1::float8,least(2::float8,100::float8/price::float8)) * quality_factor * p_marketing_factor * demand_factor * v)::bigint;
  for batch in select value from jsonb_array_elements(stock) loop
    available := available + (batch->>'quantity')::bigint;
  end loop;
  sold := least(demand,available); left_to_sell := sold;
  for batch in select value from jsonb_array_elements(stock) loop
    consumed := least(left_to_sell,(batch->>'quantity')::bigint);
    cost_of_sales := cost_of_sales + consumed*(batch->>'unitCost')::bigint;
    quantity := (batch->>'quantity')::bigint - consumed; left_to_sell := left_to_sell - consumed;
    if quantity > 0 then remaining_stock := remaining_stock || jsonb_build_array(jsonb_build_object('quantity',quantity,'unitCost',(batch->>'unitCost')::bigint)); end if;
  end loop;
  revenue := sold*price; cash_end := p_cash-purchase-marketing+revenue;
  return jsonb_build_object('cashStart',p_cash,'cashEnd',cash_end,'purchase',purchase,'unitCost',unit_cost,
    'marketing',marketing,'revenue',revenue,'costOfSales',cost_of_sales,'profit',revenue-cost_of_sales-marketing,
    'sold',sold,'demand',demand,'inventory',remaining_stock,'event',p_event,'ruleVersion',2);
end $$;


create or replace function side_lite_private.side_close_one(p_game uuid default null)
returns uuid language plpgsql set search_path = '' as $$
declare cy record; co record; d record; g record; ev jsonb; answer jsonb;
begin
  select c.id,c.game_id,c.event_id,s.seed into cy
    from public.lite_cycles c left join side_lite_private.lite_cycle_secrets s on s.cycle_id=c.id
    where c.status='open' and c.paused_at is null and c.ends_at<=clock_timestamp()
      and (p_game is null or c.game_id=p_game)
    order by c.ends_at,c.id for update of c skip locked limit 1;
  if not found then return null; end if;
  if cy.seed is null then raise exception 'missing cycle secret'; end if;
  select id,costs into strict g from public.lite_games where id=cy.game_id;
  if cy.event_id is not null then select effect into strict ev from public.lite_events where id=cy.event_id; end if;
  for co in select id,cash,inventory from public.lite_companies where game_id=g.id order by id for update loop
    select quality,quantity,price,marketing_amount into d from public.lite_decisions
      where game_id=g.id and cycle_id=cy.id and company_id=co.id and confirmed;
    answer := side_lite_private.side_engine_v2(co.cash,co.inventory,
      case when found then jsonb_build_object('quality',d.quality,'quantity',d.quantity,'price',d.price,'marketingAmount',d.marketing_amount) else null end,
      g.costs,ev,cy.seed::text,co.id::text);
    update public.lite_companies set cash=(answer->>'cashEnd')::integer,inventory=answer->'inventory' where id=co.id and game_id=g.id;
  end loop;
  update public.lite_cycles set status='closed' where id=cy.id and status='open';
  return cy.id;
end $$;


create or replace function side_lite_private.side_sweep()
returns jsonb language plpgsql set search_path = '' as $$
declare cy record; closed_id uuid; closed_count integer := 0; failed_count integer := 0;
begin
  for cy in select id,game_id from public.lite_cycles where status='open' and paused_at is null
    and ends_at<=clock_timestamp() order by ends_at,id loop
    begin
      closed_id := side_lite_private.side_close_one(cy.game_id);
      if closed_id is not null then closed_count := closed_count + 1; end if;
    exception when others then
      failed_count := failed_count + 1;
      raise warning 'SIDE-LITE cycle close failed: cycle %, SQLSTATE %', cy.id, sqlstate;
    end;
  end loop;
  return jsonb_build_object('closed',closed_count,'failed',failed_count);
end $$;

-- Commit each closure independently to release locks and isolate failures.
create or replace procedure side_lite_private.side_cron_sweep()
language plpgsql as $$
declare cy record;
begin
  for cy in select id,game_id from public.lite_cycles where status='open' and paused_at is null
    and ends_at<=pg_catalog.clock_timestamp() order by ends_at,id loop
    begin
      perform side_lite_private.side_close_one(cy.game_id);
    exception when others then
      raise warning 'SIDE-LITE cycle close failed: cycle %, SQLSTATE %', cy.id, sqlstate;
    end;
    commit;
  end loop;
end $$;
revoke all on function side_lite_private.side_engine_v2(bigint,jsonb,jsonb,jsonb,jsonb,text,text) from public, anon, authenticated, service_role;
revoke all on function side_lite_private.side_close_one(uuid) from public, anon, authenticated, service_role;
revoke all on function side_lite_private.side_sweep() from public, anon, authenticated, service_role;
revoke all on procedure side_lite_private.side_cron_sweep() from public, anon, authenticated, service_role;
grant execute on function side_lite_private.side_engine_v2(bigint,jsonb,jsonb,jsonb,jsonb,text,text) to side_lite_closer;
grant execute on function side_lite_private.side_close_one(uuid) to side_lite_closer;
grant execute on function side_lite_private.side_sweep() to side_lite_closer;
-- Cron is intentionally installed separately, after verification of this migration.
